SELECT p.id, p.user_id, p.title, p.content, p.created_at, p.category_id, p.audit_status, p.like_count, c.name AS category_name, GROUP_CONCAT(t.name ORDER BY t.name SEPARATOR ',') AS tag_names FROM post p JOIN category c ON p.category_id = c.id AND c.status = 1 LEFT JOIN post_tag pt ON p.id = pt.post_id LEFT JOIN tag t ON pt.tag_id = t.id AND t.status = 1 WHERE p.status = 1 AND p.audit_status = 1
AND p.title LIKE CONCAT('%', #{title}, '%')
AND p.category_id = #{categoryId}
GROUP BY p.id ORDER BY p.created_at DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(1) FROM post p JOIN category c ON p.category_id = c.id AND c.status = 1 WHERE p.status = 1 AND p.audit_status = 1
AND p.title LIKE CONCAT('%', #{title}, '%')
AND p.category_id = #{categoryId}

